import java.math.BigDecimal;

// One discount rule, no second variant planned -> a plain method beats Strategy.
class CartService {
    BigDecimal totalAfterDiscount(BigDecimal subtotal) {
        // 10% off for everyone today; add Strategy only when a 2nd rule appears.
        return subtotal.multiply(new BigDecimal("0.90"));
    }
}

