// CREATIONAL - control instantiation (Factory)
interface Payment { void pay(double amt); }
class Card implements Payment { public void pay(double a){ System.out.println("card " + a); } }
class PaymentFactory { static Payment of(String type){ return new Card(); } }

// STRUCTURAL - compose objects (Decorator wraps a Payment)
class LoggedPayment implements Payment {
    private final Payment inner;
    LoggedPayment(Payment p){ this.inner = p; }
    public void pay(double a){ System.out.println("log: paying"); inner.pay(a); }
}

// BEHAVIORAL - vary behavior at runtime (Strategy)
interface Discount { double apply(double price); }
class Festive implements Discount { public double apply(double p){ return p * 0.8; } }

public class Demo {
    public static void main(String[] args){
        Payment p = new LoggedPayment(PaymentFactory.of("card")); // creational + structural
        Discount d = new Festive();                                // behavioral
        p.pay(d.apply(100));
    }
}
```

