// Signal: an if-else switching on a TYPE to pick behavior -> Strategy
double discountSmell(String customerType, double price) {
    if (customerType.equals("PREMIUM")) return price * 0.85;   // behavior varies by type
    else                                return price * 0.95;   // <- the Strategy signal
}

// Refactored once the signal is recognized:
interface DiscountStrategy { double apply(double price); }
class PremiumDiscount  implements DiscountStrategy { public double apply(double p){ return p * 0.85; } }
class StandardDiscount implements DiscountStrategy { public double apply(double p){ return p * 0.95; } }
// Now a new customer type = a new class, with no edits to existing logic.
