// Over-engineered: Factory for one implementation
interface DiscountCalculatorFactory {
    DiscountCalculator create();
}

class StandardDiscountCalculatorFactory implements DiscountCalculatorFactory {
    public DiscountCalculator create() { return new StandardDiscountCalculator(); }
}

// Simpler: direct instantiation when you have one variant
@Service
public class CartService {
    private final DiscountCalculator calculator = new StandardDiscountCalculator();

    public BigDecimal calculateTotal(Cart cart) {
        var subtotal = cart.items().stream()
            .map(Item::price)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        return calculator.applyDiscount(subtotal, cart.customerId());
    }
}

// Introduce Factory only when you actually need multiple variants
// Until then, the simple version is better — 3 lines vs 15 lines
